import csv,json
rows=list(csv.DictReader(open('data.csv',newline='')))
groups={}
for r in rows: groups.setdefault(r['label'],[]).append(r)
def num(x):
    try: return float(x)
    except ValueError: return None
def f(x):
    if x is None: return 'NaN'
    s=repr(float(x))
    return s[:-2] if s.endswith('.0') else s
res=[]
for lab in sorted(groups):
    g=groups[lab]
    vals=[v for v in (num(r['value']) for r in g) if v is not None]
    total=sum(vals) if vals else 0.0
    avg=sum(vals)/len(vals) if vals else None
    n=len([r for r in g if r['id']!=''])
    mn=min(vals) if vals else None
    mx=max(vals) if vals else None
    if total>2: res.append((lab,total,avg,n,mn,mx))
out={'exit':0}
for i,(lab,total,avg,n,mn,mx) in enumerate(res,1):
    out['label_%d'%i]=lab
    out['total_%d'%i]=f(total)
    out['avg_%d'%i]=f(avg)
    out['num_%d'%i]=str(n)
    out['mn_%d'%i]=f(mn)
    out['mx_%d'%i]=f(mx)
print(json.dumps(out))

